import{_ as r,l as t,o as a,c as i,v as o,p as n,x as c,d as p,i as s,S as l}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"C 预处理器","description":"","frontmatter":{"title":"C 预处理器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/c-preprocessor.md","filePath":"cs/c-preprocessor.md","lastUpdated":1789023840000}'),h={name:"cs/c-preprocessor.md"};function f(m,e,_,u,C,E){const d=t("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="c-预处理器" tabindex="-1">C 预处理器 <a class="header-anchor" href="#c-预处理器" aria-label="Permalink to &quot;C 预处理器&quot;">​</a></h1><div class="epigraph"><p>在真正的 C 语法之前，cpp 按记号列表做替换、条件编译与文件包含。它不是卫生宏，也不是函数。</p><footer>—— 据 ISO C 标准预处理翻译阶段；Kernighan and Ritchie；龙书对独立预处理遍的说明整理</footer></div><p>上一课<a href="/cs/macros-hygiene">宏与卫生</a>给出着色宏的不变量。C 的 <code>#define</code> 工作在<strong>词法记号</strong>上，故意不卫生，且发生在<a href="/cs/lex-flex">lex</a> 与语法之间的标准「翻译阶段」。缺口是这份<strong>阶段与陷阱</strong>：包含、条件、粘贴、字符串化，不是再讲 Scheme。本课钉顺序，不写全部 <code>#pragma</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ISO C 把翻译分成阶段：物理源 → 逻辑行（续行符）→ 记号 → 预处理 → 再记号化 → 语法。<code>#include</code> 把另一文件的记号插进来，符号表与 AST 尚未存在。缺口是<strong>预处理遍的输入输出类型</strong>：仍是记号流，不是树。</p><p>函数式宏 <code>#define F(a) ...</code> 只认括号调用，有独立的展开规则（参数预扩展、<code>#</code> <code>##</code>）。与卫生宏对照：<code>tmp</code> 必捕获。</p><h3 id="define-不是类型系统" tabindex="-1"><code>#define</code> 不是类型系统 <a class="header-anchor" href="#define-不是类型系统" aria-label="Permalink to &quot;`#define` 不是类型系统&quot;">​</a></h3><p>宏不尊重作用域、不尊重 <code>typedef</code>。<code>max(x++, y)</code> 双求值是展开副本，不是调用约定。本课用这个例子钉「改写 ≠ 函数」，不重讲求值策略。</p><p><span class="marginnote">K&amp;R 与 ISO C 的翻译阶段。cpp 可独立运行（<code>cc -E</code>）。本课不把模块（C++20 modules / C23 的部分方向）当已替代 cpp 的事实。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现：维护宏表与条件编译栈（<code>#if</code>/<code>#ifdef</code>）。展开时防递归（已展开的宏名涂黑）。<code>##</code> 粘贴后须再扫描。包含路径与守卫（<code>#ifndef</code>）是工程，不是文法。</p>',11)),(a(),n(l,null,{default:c(()=>[s(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E6%96%87%E4%BB%B6%22%5D%20--%3E%20CPP%5B%22%E9%A2%84%E5%A4%84%E7%90%86%22%5D%0A%20%20INC%5B%22%23include%22%5D%20--%3E%20CPP%0A%20%20CPP%20--%3E%20TOK%5B%22%E5%B1%95%E5%BC%80%E5%90%8E%E8%AE%B0%E5%8F%B7%22%5D%0A%20%20TOK%20--%3E%20PARSE%5B%22C%20%E8%AF%AD%E6%B3%95%22%5D%0A"})]),fallback:c(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与 lex：有的实现把 cpp 与扫描器交织（上下文敏感的 <code>typedef</code> 还在后面）。标准仍要求阶段语义。错误：<code>#error</code>、未定义行为式的粘贴结果，诊断要指向宏调用栈。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>条件编译改变「哪些记号存在」，分析器看见的语言是配置后的。增量解析若忽略 cpp，高亮与真编译会分叉——接<a href="/cs/incremental-parsing">tree-sitter</a> 的边界。</p><p>卫生课的着色在 cpp 里不存在：要卫生只能不用 cpp 做绑定。头文件是文本接口，不是模块类型检查。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写链接，不讲导出宏的 ABI。后课默认：C 前端先预处理再分析；捕获与双求值是特性。下一课：源编码与 Unicode 词法——在 cpp 之前的字符阶段。</p><p>不要把 <code>X</code> 宏表技巧当类型安全的泛型；泛型在类型单元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cpp 在语法前改记号；不卫生、无作用域。</li><li>翻译阶段规定包含与宏的顺序。</li><li><code>#</code>/<code>##</code> 与参数预扩展是独立规则。</li><li>出处：ISO C；Kernighan and Ritchie；对照 Kohlbecker 卫生宏。</li></ul>',9))])}const x=r(h,[["render",f]]);export{A as __pageData,x as default};
